0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4831,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 18.67\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T6a0,"])self.__next_f.push([1,"Persons who have not undergone the austerities of the religious process, who have never attempted devotional service in Kṛṣṇa consciousness, who have not tended a pure devotee, and especially those who are conscious of Kṛṣṇa only as a historical personality or who are envious of the greatness of Kṛṣṇa should not be told this most confidential part of knowledge. It is, however, sometimes found that even demoniac persons who are envious of Kṛṣṇa, worshiping Kṛṣṇa in a different way, take to the profession of explaining Bhagavad-gītā in a different way to make business, but anyone who desires actually to understand Kṛṣṇa must avoid such commentaries on Bhagavad-gītā. Actually the purpose of Bhagavad-gītā is not understandable to those who are sensuous. Even if one is not sensuous but is strictly following the disciplines enjoined in the Vedic scripture, if he is not a devotee he also cannot understand Kṛṣṇa. And even when one poses himself as a devotee of Kṛṣṇa but is not engaged in Kṛṣṇa conscious activities, he also cannot understand Kṛṣṇa. There are many persons who envy Kṛṣṇa because He has explained in Bhagavad-gītā that He is the Supreme and that nothing is above Him or equal to Him. There are many persons who are envious of Kṛṣṇa. Such persons should not be told of Bhagavad-gītā, for they cannot understand. There is no possibility of faithless persons’ understanding Bhagavad-gītā and Kṛṣṇa. Without understanding Kṛṣṇa from the authority of a pure devotee, one should not try to comment upon Bhagavad-gītā."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4831,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"67\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 67\",\"advanced_view_url_path\":\"/en/library/bg/18/advanced-view/#bb4227\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/18/67/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/18/67/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/18/67/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/18/67/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/18/67/\"},{\"displa